  NULL::fountain.external_place_matches,
  $ih_external_place_matches$[{"rating":4.5,"provider":"google_places","raw_json":{"id":"ChIJowi7Xk25woARcU2u2j6jfms","rating":4.5,"reviews":[{"name":"places/ChIJowi7Xk25woARcU2u2j6jfms/reviews/ChdDSUhNMG9nS0VNSDF3ZDJudzlqQ3p3RRAB","text":{"text":"I had an excellent experience with Dr. Daneshrad and his team. He is incredibly knowledgeable and takes the time to explain everything clearly, making sure you feel informed and comfortable every step of the way. His bedside manner is truly exceptional — kind, attentive, and patient. It’s clear he genuinely cares about his patients’ well-being.\n\nThe staff is just as impressive — professional, friendly, and always accommodating. From check-in to follow-up, everything was smooth and organized. I felt respected and well taken care of throughout my visits. Highly recommend Dr. Daneshrad for anyone in need of a caring and competent cardiologist!","languageCode":"en"},"rating":5,"publishTime":"2025-06-05T05:09:02.553515Z","originalText":{"text":"I had an excellent experience with Dr. Daneshrad and his team. He is incredibly knowledgeable and takes the time to explain everything clearly, making sure you feel informed and comfortable every step of the way. His bedside manner is truly exceptional — kind, attentive, and patient. It’s clear he genuinely cares about his patients’ well-being.\n\nThe staff is just as impressive — professional, friendly, and always accommodating. From check-in to follow-up, everything was smooth and organized. I felt respected and well taken care of throughout my visits. Highly recommend Dr. Daneshrad for anyone in need of a caring and competent cardiologist!","languageCode":"en"},"googleMapsUri":"https://www.google.com/maps/reviews/data=!4m6!14m5!1m4!2m3!1sChdDSUhNMG9nS0VNSDF3ZDJudzlqQ3p3RRAB!2m1!1s0x80c2b94d5ebb08a3:0x6b7ea33edaae4d71","flagContentUri":"https://www.google.com/local/content/rap/report?postId=ChdDSUhNMG9nS0VNSDF3ZDJudzlqQ3p3RRAB&d=17924085&t=1","authorAttribution":{"uri":"https://www.g