DO $preflight$
BEGIN
  IF (SELECT count(*) FROM ih_cohort) <> 62
     OR (SELECT count(*) FROM ih_locations) <> 62
     OR EXISTS (SELECT 1 FROM ih_cohort WHERE final_decision <> 'ready')
     OR EXISTS (SELECT 1 FROM ih_locations WHERE id = 14609) THEN
    RAISE EXCEPTION 'Impossible Health promotion payload failed cohort preflight';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM ih_locations incoming
    JOIN fountain.locations existing
      ON existing.id <> incoming.id
     AND existing.deleted_at IS NULL
     AND existing.status = 'active'
     AND lower(regexp_replace(coalesce(existing.name, ''), '[^a-z0-9]', '', 'g'))
       = lower(regexp_replace(coalesce(incoming.name, ''), '[^a-z0-9]', '', 'g'))
     AND lower(regexp_replace(coalesce(existing.address, ''), '[^a-z0-9]', '', 'g'))
       = lower(regexp_replace(coalesce(incoming.address, ''), '[^a-z0-9]', '', 'g'))
  ) THEN
    RAISE EXCEPTION 'Impossible Health promotion found a new exact production duplicate';
  END IF;
END
$preflight$;

INSERT INTO fountain.organizations (
  id, canonical_name, name_normalized, website_domain, description, dedup_key,
  public_id, status, data_origin, verification_status, created_at, updated_at,
  deleted_at, owner_account_id
)
SELECT
  id, canonical_name, name_normalized, website_domain, description, dedup_key,
  public_id, status, data_origin, verification_status, created_at, updated_at,
  deleted_at, owner_account_id
FROM ih_organizations
ON CONFLICT (id) DO UPDATE SET
  canonical_name = EXCLUDED.canonical_name,
  name_normalized = EXCLUDED.name_normalized,
  website_domain = EXCLUDED.website_domain,
  description = EXCLUDED.description,
  dedup_key = EXCLUDED.dedup_key,
  status = EXCLUDED.status,
  data_origin = EXCLUDED.data_origin,
  verification_status = EXCLUDED.verification_status,
  deleted_at = EXCLUDED.deleted_at;

INSERT INTO fountain.sources (id, slug, trust_weight, offering_granularity)
SELECT id, slug, trust_weight, offering_granularity
FROM ih_sources
ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug,
  trust_weight = EXCLUDED.trust_weight,
  offering_granularity = EXCLUDED.offering_granularity;

INSERT INTO fountain.locations (
  id, org_id, name, address, locality, region, postal_code, country_code,
  country_name, latitude, longitude, phone, email, website, dedup_key,
  public_id, status, data_origin, verification_status, created_at, updated_at,
  deleted_at, owner_account_id, slug, is_virtual
)
SELECT
  id, org_id, name, address, locality, region, postal_code, country_code,
  country_name, latitude, longitude, phone, email, website, dedup_key,
  public_id, status, data_origin, verification_status, created_at, updated_at,
  deleted_at, owner_account_id, slug, is_virtual
FROM ih_locations
ON CONFLICT (id) DO UPDATE SET
  org_id = EXCLUDED.org_id,
  name = EXCLUDED.name,
  address = EXCLUDED.address,
  locality = EXCLUDED.locality,
  region = EXCLUDED.region,
  postal_code = EXCLUDED.postal_code,
  country_code = EXCLUDED.country_code,
  country_name = EXCLUDED.country_name,
  latitude = EXCLUDED.latitude,
  longitude = EXCLUDED.longitude,
  phone = EXCLUDED.phone,
  email = EXCLUDED.email,
  website = EXCLUDED.website,
  dedup_key = EXCLUDED.dedup_key,
  status = EXCLUDED.status,
  data_origin = EXCLUDED.data_origin,
  verification_status = EXCLUDED.verification_status,
  deleted_at = EXCLUDED.deleted_at,
  slug = EXCLUDED.slug,
  is_virtual = EXCLUDED.is_virtual;

SELECT setval(
  pg_get_serial_sequence('fountain.organizations', 'id'),
  (SELECT max(id) FROM fountain.organizations),
  true
);
SELECT setval(
  pg_get_serial_sequence('fountain.sources', 'id'),
  (SELECT max(id) FROM fountain.sources),
  true
);
SELECT setval(
  pg_get_serial_sequence('fountain.locations', 'id'),
  (SELECT max(id) FROM fountain.locations),
  true
);

-- Replace the selected cohort menus so production matches the reviewed preview
-- exactly, including the reviewer-corrected official prices and no-price items.
DELETE FROM fountain.offerings
WHERE location_id IN (SELECT location_id FROM ih_cohort);

INSERT INTO fountain.offerings (
  location_id, treatment_id, raw_name, price_amount, price_currency,
  source_offer_url, source_id, status, data_origin, verification_status,
  created_at, updated_at, deleted_at, owner_account_id
)
SELECT
  location_id, treatment_id, raw_name, price_amount, price_currency,
  source_offer_url, source_id, status, data_origin, verification_status,
  created_at, updated_at, deleted_at, owner_account_id
FROM ih_offerings;

-- Keep historical image rows, but make the reviewed image the only active image
-- for each promoted listing.
UPDATE fountain.images
SET status = 'hidden'
WHERE entity_type = 'location'
  AND entity_id IN (SELECT location_id FROM ih_cohort)
  AND status = 'active'
  AND deleted_at IS NULL;

UPDATE fountain.images existing
SET
  image_url = reviewed.image_url,
  content_sha256 = reviewed.content_sha256,
  alt = reviewed.alt,
  source_id = reviewed.source_id,
  status = 'active',
  data_origin = reviewed.data_origin,
  verification_status = reviewed.verification_status,
  deleted_at = NULL,
  owner_account_id = reviewed.owner_account_id,
  image_kind = reviewed.image_kind
FROM ih_images reviewed
WHERE existing.entity_type = reviewed.entity_type
  AND existing.entity_id = reviewed.entity_id
  AND existing.blob_url = reviewed.blob_url;

INSERT INTO fountain.images (
  entity_type, entity_id, image_url, blob_url, content_sha256, alt,
  source_id, status, data_origin, verification_status, created_at, updated_at,
  deleted_at, owner_account_id, image_kind
)
SELECT
  reviewed.entity_type, reviewed.entity_id, reviewed.image_url, reviewed.blob_url,
  reviewed.content_sha256, reviewed.alt, reviewed.source_id, reviewed.status,
  reviewed.data_origin, reviewed.verification_status, reviewed.created_at,
  reviewed.updated_at, reviewed.deleted_at, reviewed.owner_account_id,
  reviewed.image_kind
FROM ih_images reviewed
WHERE NOT EXISTS (
  SELECT 1
  FROM fountain.images existing
  WHERE existing.entity_type = reviewed.entity_type
    AND existing.entity_id = reviewed.entity_id
    AND existing.blob_url = reviewed.blob_url
);

INSERT INTO fountain.source_records (
  source_id, entity_type, entity_id, source_listing_id, source_url, raw_ref
)
SELECT
  reviewed.source_id, reviewed.entity_type, reviewed.entity_id,
  reviewed.source_listing_id, reviewed.source_url, reviewed.raw_ref
FROM ih_source_records reviewed
WHERE NOT EXISTS (
  SELECT 1
  FROM fountain.source_records existing
  WHERE existing.source_id = reviewed.source_id
    AND existing.entity_type = reviewed.entity_type
    AND existing.entity_id = reviewed.entity_id
    AND existing.source_listing_id IS NOT DISTINCT FROM reviewed.source_listing_id
    AND existing.source_url IS NOT DISTINCT FROM reviewed.source_url
    AND existing.raw_ref IS NOT DISTINCT FROM reviewed.raw_ref
);

INSERT INTO fountain.external_place_matches (
  location_id, provider, provider_place_id, provider_url, display_name,
  rating, review_count, match_confidence, match_status, fetched_at,
  expires_at, raw_json
)
SELECT
  location_id, provider, provider_place_id, provider_url, display_name,
  rating, review_count, match_confidence, match_status, fetched_at,
  expires_at, raw_json
FROM ih_external_place_matches
ON CONFLICT (location_id, provider) DO UPDATE SET
  provider_place_id = EXCLUDED.provider_place_id,
  provider_url = EXCLUDED.provider_url,
  display_name = EXCLUDED.display_name,
  rating = EXCLUDED.rating,
  review_count = EXCLUDED.review_count,
  match_confidence = EXCLUDED.match_confidence,
  match_status = EXCLUDED.match_status,
  fetched_at = EXCLUDED.fetched_at,
  expires_at = EXCLUDED.expires_at,
  raw_json = EXCLUDED.raw_json;

CREATE TABLE IF NOT EXISTS fountain_raw.impossible_health_promotion_audit_20260713 (
  location_id integer PRIMARY KEY,
  source_candidate_id integer NOT NULL,
  approval_source text NOT NULL,
  promotion_action text NOT NULL,
  advisories text[] NOT NULL DEFAULT '{}',
  promoted_at timestamptz NOT NULL DEFAULT now(),
  actor_id uuid NOT NULL
);

INSERT INTO fountain_raw.impossible_health_promotion_audit_20260713 (
  location_id, source_candidate_id, approval_source, promotion_action,
  advisories, promoted_at, actor_id
)
SELECT
  cohort.location_id,
  cohort.source_candidate_id,
  cohort.approval_source,
  CASE WHEN cohort.location_id <= 14606 THEN 'updated_existing' ELSE 'inserted_new' END,
  coalesce(cohort.advisories, '{}'),
  now(),
  'b5c71897-83d0-4c30-a7a3-202607130018'::uuid
FROM ih_cohort cohort
ON CONFLICT (location_id) DO UPDATE SET
  source_candidate_id = EXCLUDED.source_candidate_id,
  approval_source = EXCLUDED.approval_source,
  promotion_action = EXCLUDED.promotion_action,
  advisories = EXCLUDED.advisories,
  promoted_at = EXCLUDED.promoted_at,
  actor_id = EXCLUDED.actor_id;

DO $verify$
BEGIN
  IF (SELECT count(*) FROM fountain.locations l JOIN ih_cohort c ON c.location_id = l.id WHERE l.status = 'active' AND l.deleted_at IS NULL) <> 62 THEN
    RAISE EXCEPTION 'Impossible Health promotion verification failed: expected 62 active locations';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM ih_cohort cohort
    JOIN fountain.locations location ON location.id = cohort.location_id
    WHERE nullif(btrim(location.address), '') IS NULL
       OR nullif(btrim(location.phone), '') IS NULL
       OR nullif(btrim(location.website), '') IS NULL
       OR NOT EXISTS (
         SELECT 1 FROM fountain.offerings offering
         WHERE offering.location_id = cohort.location_id
           AND offering.status = 'active'
           AND offering.deleted_at IS NULL
       )
       OR NOT EXISTS (
         SELECT 1 FROM fountain.images image
         WHERE image.entity_type = 'location'
           AND image.entity_id = cohort.location_id
           AND image.status = 'active'
           AND image.deleted_at IS NULL
       )
  ) THEN
    RAISE EXCEPTION 'Impossible Health promotion verification failed: mandatory fields are incomplete';
  END IF;

  IF (SELECT count(*) FROM fountain.offerings offering JOIN ih_cohort cohort ON cohort.location_id = offering.location_id WHERE offering.status='active' AND offering.deleted_at IS NULL)
     <> (SELECT count(*) FROM ih_offerings) THEN
    RAISE EXCEPTION 'Impossible Health promotion verification failed: offering count mismatch';
  END IF;

  IF (SELECT count(*) FROM fountain.images image JOIN ih_cohort cohort ON cohort.location_id = image.entity_id WHERE image.entity_type='location' AND image.status='active' AND image.deleted_at IS NULL)
     <> (SELECT count(*) FROM ih_images) THEN
    RAISE EXCEPTION 'Impossible Health promotion verification failed: image count mismatch';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM ih_locations incoming
    JOIN fountain.locations existing
      ON existing.id <> incoming.id
     AND existing.deleted_at IS NULL
     AND existing.status = 'active'
     AND lower(regexp_replace(coalesce(existing.name, ''), '[^a-z0-9]', '', 'g'))
       = lower(regexp_replace(coalesce(incoming.name, ''), '[^a-z0-9]', '', 'g'))
     AND lower(regexp_replace(coalesce(existing.address, ''), '[^a-z0-9]', '', 'g'))
       = lower(regexp_replace(coalesce(incoming.address, ''), '[^a-z0-9]', '', 'g'))
  ) THEN
    RAISE EXCEPTION 'Impossible Health promotion verification failed: exact duplicate remains';
  END IF;
END
$verify$;

COMMIT;
